// ESLint flat config: the recommended rules over every hand-written script. npm run lint, in the engine job.
import js from '@eslint/js';
import globals from 'globals';

export default [
  // dist/ is generated by npm run build; demo/out/ holds rendered media.
  { ignores: ['dist/', 'demo/out/', 'java/', 'playwright-report/', 'test-results/'] },
  js.configs.recommended,
  // engine/ is pure and runs in both the browser and Node, so it gets no host globals.
  { files: ['ui/**/*.js'], languageOptions: { globals: globals.browser } },
  { files: ['scripts/**', 'checks/**', 'test/**', 'demo/**', '*.config.js'], languageOptions: { globals: globals.node } },
  // Playwright specs and the demo capture also pass callbacks to page.evaluate, which run in the browser.
  { files: ['checks/ui/**', 'demo/capture.mjs'], languageOptions: { globals: { ...globals.node, ...globals.browser } } },
];
